import {drawBossWarning} from './telegraphs-v14.js';
import {drawPaintedEffect,drawPaintedProjectile} from './combat-visuals-v14.js';
// Contact effects use the original painted VFX atlas; light and trails remain anchored to the weapon/feet.
const anchors=[224,152,218,220,220,220];
function frame(c,bank,row,index,x,y,size,angle=0,alpha=1){const image=bank.images.qualityFX;if(!image)return false;const sw=image.width/4,sh=image.height/6;c.save();c.globalAlpha*=alpha;c.translate(x,y);c.rotate(angle);c.drawImage(image,index*sw,row*sh,sw,sh,-size*.5,-size*anchors[row]/256,size,size);c.restore();return true;}
function glow(c,x,y,r,color,alpha=.6){c.save();c.globalAlpha*=alpha;const g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(.2,color+'a0');g.addColorStop(1,color+'00');c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2);c.restore();}
function motes(c,x,y,r,t,color,count=14,rise=0){c.save();c.fillStyle=color;for(let i=0;i<count;i++){const a=i*2.3999,d=r*(.3+.7*((i*.618)%1));const px=x+Math.cos(a)*d*t,py=y+Math.sin(a)*d*t*.58-rise*t;c.globalAlpha=(1-t)*(.4+(i%3)*.2);c.beginPath();c.ellipse(px,py,1.8+(i%3)*.5,1.2, a,0,7);c.fill();}c.restore();}
export function drawSpriteEffectV9(c,bank,f,time){if(drawPaintedEffect(c,bank,f,time))return true;const t=1-f.life/f.max;
 if(/^(holy|ashShield|soulBind|bloodPact|graveBell|machine)/.test(f.type)){const holy=f.type.startsWith('holy'),color=holy?'#fff0ba':f.color||'#a7dbe4';c.save();c.globalCompositeOperation='screen';glow(c,f.x,f.y-35,f.r*.7,color,(1-t)*.23);motes(c,f.x,f.y-18,f.r,t,color,holy?20:12,holy?48:18);if(/Shield|shield|Aegis/.test(f.type)){for(const flip of [-1,1]){c.strokeStyle=color;c.globalAlpha=(1-t)*.65;c.lineWidth=2;for(let i=0;i<4;i++){c.beginPath();c.moveTo(f.x+flip*15,f.y-38);c.quadraticCurveTo(f.x+flip*(32+i*5),f.y-54-i*5,f.x+flip*(21+i*5),f.y-13+i*4);c.stroke();}}}if(/Nova|graveBell/.test(f.type)){c.strokeStyle=color;c.globalAlpha=(1-t)*.7;c.lineWidth=3;c.beginPath();c.ellipse(f.x,f.y,f.r*(.35+.65*t),f.r*(.2+.34*t),0,0,7);c.stroke();}if(f.type==='holyChime'){c.strokeStyle=color;c.lineWidth=2;c.globalAlpha=1-t;c.beginPath();c.moveTo(f.x-10,f.y-82);c.quadraticCurveTo(f.x-15,f.y-109,f.x,f.y-107);c.quadraticCurveTo(f.x+15,f.y-109,f.x+10,f.y-82);c.closePath();c.stroke();}c.restore();return true;}
 if(f.type==='sparks'){motes(c,f.x,f.y,f.r,t,f.color||'#f0c799',8,6);return true;}
 if(f.type==='enemyCut'&&['rat','wolf','hellHound','bat'].includes(f.enemyType)){c.save();c.translate(f.x,f.y);c.rotate(f.a||0);c.strokeStyle='#ead7b2';c.globalAlpha=(1-t)*.75;c.lineWidth=2;for(let i=-1;i<=1;i++){c.beginPath();c.moveTo(-10,-10+i*6);c.quadraticCurveTo(5,-2+i*6,20,8+i*6);c.stroke();}c.restore();return true;}
 const row={cut:0,enemyCut:0,spin:0,streak:4,trail:4,impact:5,debris:5,fall:5,flame:1,frost:2,guard:3,shield:3}[f.type];if(row===undefined)return false;const phase=Math.min(3,Math.floor(t*4));let size=Math.max(32,Math.min(220,f.r*1.35));if(f.type==='enemyCut')size=Math.min(80,size);return frame(c,bank,row,phase,f.x,f.y+12,size,['cut','enemyCut','streak','trail'].includes(f.type)?(f.a||0)+.4:0,Math.min(1,(1-t)*2));}
export function drawProjectileV9(c,bank,b,time){if(drawPaintedProjectile(c,bank,b,time))return true;const holy=b.holy,enemy=!b.friendly,color=holy?'#fff0b8':enemy?b.enemyType==='hellSoul'?'#a2deed':'#d5b298':b.skillKey==='emberLance'?'#ffc788':b.color||'#e7af75';const a=Math.atan2(b.vy,b.vx);c.save();c.translate(b.x,b.y);c.rotate(a);c.globalCompositeOperation='screen';const g=c.createLinearGradient(-32,0,8,0);g.addColorStop(0,color+'00');g.addColorStop(.75,color+'a0');g.addColorStop(1,'#fff8df');c.fillStyle=g;c.beginPath();c.moveTo(10,0);c.quadraticCurveTo(-5,-(holy?4:5),-34,-1);c.lineTo(-34,1);c.quadraticCurveTo(-5,5,10,0);c.fill();glow(c,0,0,holy?15:12,color,.35);c.restore();return true;}
export function drawTelegraphV9(c,bank,e,time){return drawBossWarning(c,bank,e,time);}
